"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[66734],{66734:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/greenhouse-at-the-end-of-the-world.png\\"\\n          title=\\"지구 끝의 온실\\"\\n          author=\\"김초엽\\"\\n          publisher=\\"자이언트북스\\"\\n          publishedDate=\\"2021-08-18\\"\\n          isbn=\\"9791191824001\\"\\n          rating=3.5\\n          tags=\\"sf\\"\\n        />\\n</center>\\n\\n## Review\\n```더스트(Dust)```라는 치명적인 독성 나노 먼지로 멸망 위기의 세대 이야기.  \\nSF의 단골 소재는 역시나 인류의 멸망.  \\n연출만 가능하다면 영화로 나올 수 있는 소재와 재미 요소가 있는 것 같다.  \\n<br>\\n이런 이야기에서 꼭 나오는 <mark>내성종</mark>을 대하는 인류의 양면성이 이 책에서도 그대로 드러난다.  \\n인류를 위해, 공익을 위해 꼭 희생되어야 하는 존재인가?"}')}}]);